+				return nil
+			})
+			sort.Slice(files, func(i, j int) bool {
+				return files[i].displayPath < files[j].displayPath
+			})
+			out = append(out, files...)
+			continue
+		}
+		input := inputFile{
+			displayPath: filepath.ToSlash(arg),
+			realPath:    arg,
+			size:        info.Size(),
+			language:    detectLanguage(arg, cfg.language),
+		}
+		if shouldIncludeInput(input, cfg) {
+			out = append(out, input)
+		}
+	}
+	return out
+}
+
+func shouldIncludeInput(input inputFile, cfg config) bool {
+	for _, pattern := range cfg.ignorePatterns {
+		if matchPath(pattern, input.displayPath) {
+			return false
+		}
+	}
+	if len(cfg.fileFilters) == 0 {
+		return true
+	}
+	for _, pattern := range cfg.fileFilters {
+		if pattern == "" || pattern == "-" || pattern == "+" {
+			continue
+		}
+		if matchPath(pattern, input.displayPath) {
+			return true
+		}
+	}
+	return false
+}
+
+func detectLanguage(path, forced string) string {
+	if forced == "c" || forced == "c++" {
+		return forced
+	}
+	if cppExtensions[strings.ToLower(filepath.Ext(path))] {
+		return "c++"
+	}
+	return "c"
+}
+
+func analyzeFile(input inputFile, cfg config) []diagnostic {
+	data, err := os.ReadFile(input.realPath)
+	if err != nil {
+		return nil
+	}
+
+	text := strings.ReplaceAll(string(data), "\r\n", "\n")
+	lines := strings.Split(text, "\n")
+	inlineSuppressions := collectInlineSuppressions(lines)
+
+	arrays := map[string]arrayDecl{}
+	scalars := map[string]scalarDecl{}
+	functions := map[string]functionDecl{}
+
+	for i, line := range lines {
+		trimmed := strings.TrimSpace(line)
+		if trimmed == "" || strings.HasPrefix(trimmed, "#") || strings.HasPrefix(trimmed, "//") {
+			continue
+		}
+
+		if m := arrayDeclRe.FindStringSubmatch(line); m != nil {
+			name := m[1]
+			size, _ := strconv.Atoi(m[2])
+			arrays[name] = arrayDecl{
+				name:        name,
+				size:        size,
+				line:        i + 1,
+				column:      strings.Index(line, name) + 1,
+				initialized: strings.TrimSpace(m[3]) != "",
+				code:        line,
+			}
+			continue
+		}
+
+		if m := scalarInitRe.FindStringSubmatch(line); m != nil {
+			name := m[1]
+			scalars[name] = scalarDecl{
+				name:      name,
+				line:      i + 1,
+				assignCol: strings.Index(line, "=") + 1,
+				code:      line,
+			}
+			continue
+		}
+
+		if isFunctionDefinition(lines, i, line) {
+			if m := functionRe.FindStringSubmatch(line); m != nil {
+				name := m[1]
+				functions[name] = functionDecl{
+					name:   name,
+					line:   i + 1,
+					column: strings.Index(line, name) + 1,
+				}
+			}
+		}
+	}
+
+	if diag := detectSyntaxError(input.displayPath, lines, functions); diag != nil {
+		return applyInlineSuppressions([]diagnostic{*diag}, inlineSuppressions, cfg.inlineSuppress)
+	}
+
+	var diags []diagnostic
+	emittedUninit := map[string]bool{}
+	emittedConst := map[string]bool{}
+	emittedUnassigned := map[string]bool{}
+
+	for i, line := range lines {
+		trimmed := strings.TrimSpace(line)
+		if trimmed == "" || strings.HasPrefix(trimmed, "//") {
+			continue
+		}
+		if arrayDeclRe.MatchString(line) {
+			continue
+		}
+
+		matches := arrayUseRe.FindAllStringSubmatchIndex(line, -1)
+		for _, match := range matches {
+			name := line[match[2]:match[3]]
+			indexText := line[match[4]:match[5]]
+			index, _ := strconv.Atoi(indexText)
+			decl, ok := arrays[name]
+			if !ok {
+				continue
+			}
+
+			if index >= decl.size {
+				diags = append(diags, diagnostic{
+					File:     input.displayPath,
+					Line:     i + 1,
+					Column:   match[0] + strings.Index(line[match[0]:match[1]], "[") + 1,
+					Severity: "error",
+					Message:  fmt.Sprintf("Array '%s[%d]' accessed at index %d, which is out of bounds.", name, decl.size, index),
+					ID:       "arrayIndexOutOfBounds",
+					CWE:      "788",
+					Info:     "Array index out of bounds",
+					Code:     line,
+				})
+			}
+
+			if !decl.initialized && !emittedUninit[name] {
+				if cfg.enableAll && !emittedConst[name] {
+					diags = append(diags, diagnostic{
+						File:     input.displayPath,
+						Line:     decl.line,
+						Column:   decl.column,
+						Severity: "style",
+						Message:  fmt.Sprintf("Variable '%s' can be declared as const array", name),
+						ID:       "constVariable",
+						CWE:      "398",
+						Info:     fmt.Sprintf("Variable '%s' can be declared as const array", name),
+						Symbol:   name,
+						Code:     decl.code,
+					})
+					emittedConst[name] = true
+				}
+
+				diags = append(diags, diagnostic{
+					File:     input.displayPath,
+					Line:     i + 1,
+					Column:   match[0] + 1,
+					Severity: "error",
+					Message:  fmt.Sprintf("Uninitialized variable: %s", name),
+					ID:       "uninitvar",
+					CWE:      "457",
+					Symbol:   name,
+					Code:     line,
+				})
+				emittedUninit[name] = true
+
+				if cfg.enableAll && !emittedUnassigned[name] {
+					diags = append(diags, diagnostic{
+						File:     input.displayPath,
+						Line:     decl.line,
+						Column:   decl.column,
+						Severity: "style",
+						Message:  fmt.Sprintf("Variable '%s' is not assigned a value.", name),
+						ID:       "unassignedVariable",
+						CWE:      "665",
+						Symbol:   name,
+						Code:     decl.code,
+					})
+					emittedUnassigned[name] = true
+				}
+			}
+		}
+	}
+
+	if cfg.enableStyle {
+		for _, scalar := range scalars {
+			if !isNameReadLater(lines, scalar.name, scalar.line) {
+				diags = append(diags, diagnostic{
+					File:     input.displayPath,
+					Line:     scalar.line,
+					Column:   scalar.assignCol,
+					Severity: "style",
+					Message:  fmt.Sprintf("Variable '%s' is assigned a value that is never used.", scalar.name),
+					ID:       "unreadVariable",
+					CWE:      "563",
+					Symbol:   scalar.name,
+					Code:     scalar.code,
+				})
+			}
+		}
+
+		for i, line := range lines {
+			if m := regexp.MustCompile(`\b([A-Za-z_]\w*)\s*(\[\d+\])\s*=\s*[^;]+;`).FindStringSubmatch(line); m != nil {
+				name := m[1]
+				if _, ok := arrays[name]; !ok {
+					continue
+				}
+				target := name + m[2]
+				if !isArrayReadLater(lines, name, i+1) {
+					diags = append(diags, diagnostic{
+						File:     input.displayPath,
+						Line:     i + 1,
+						Column:   strings.Index(line, "=") + 1,
+						Severity: "style",
+						Message:  fmt.Sprintf("Variable '%s' is assigned a value that is never used.", target),
+						ID:       "unreadVariable",
+						CWE:      "563",
+						Symbol:   target,
+						Code:     line,
+					})
+				}
+			}
+		}
+	}
+
+	if cfg.enableUnusedFunc {
+		used := map[string]bool{}
+		for i, line := range lines {
+			matches := funcCallRe.FindAllStringSubmatchIndex(line, -1)
+			for _, match := range matches {
+				name := line[match[2]:match[3]]
+				if fn, ok := functions[name]; ok {
+					if fn.line == i+1 && isFunctionDefinition(lines, i, line) {
+						continue
+					}
+				}
+				used[name] = true
+			}
+		}
+		var names []string
+		for name := range functions {
+			names = append(names, name)
+		}
+		sort.Strings(names)
+		for _, name := range names {
+			fn := functions[name]
+			if name == "main" || used[name] {
+				continue
+			}
+			diags = append(diags, diagnostic{
+				File:     input.displayPath,
+				Line:     fn.line,
+				Column:   fn.column,
+				Severity: "style",
+				Message:  fmt.Sprintf("The function '%s' is never used.", name),
+				ID:       "unusedFunction",
+				CWE:      "561",
+				Symbol:   name,
+				Code:     lines[fn.line-1],
+				OmitFile0: true,
+			})
+		}
+	}
+
+	return applyInlineSuppressions(diags, inlineSuppressions, cfg.inlineSuppress)
+}
+
+func detectSyntaxError(path string, lines []string, functions map[string]functionDecl) *diagnostic {
+	for i := 0; i < len(lines)-1; i++ {
+		current := strings.TrimSpace(lines[i])
+		if current == "" || strings.HasPrefix(current, "//") {
+			continue
+		}
+		if strings.HasSuffix(current, ";") || strings.HasSuffix(current, "{") || strings.HasSuffix(current, "}") || strings.HasSuffix(current, ":") {
+			continue
+		}
+
+		nextIndex := nextMeaningfulLine(lines, i+1)
+		if nextIndex < 0 {
+			break
+		}
+		next := strings.TrimSpace(lines[nextIndex])
+		if strings.HasPrefix(next, "return") {
+			tokens := strings.Fields(current)
+			last := ""
+			if len(tokens) > 0 {
+				last = tokens[len(tokens)-1]
+			}
+			msg := "syntax error"
+			if last != "" {
+				msg = fmt.Sprintf("syntax error: %s return", last)
+			}
+			col := firstNonSpaceColumn(lines[nextIndex])
+			return &diagnostic{
+				File:     path,
+				Line:     nextIndex + 1,
+				Column:   col,
+				Severity: "error",
+				Message:  msg,
+				ID:       "syntaxError",
+				Code:     lines[nextIndex],
+			}
+		}
+	}
+
+	hasCShape := false
+	for _, line := range lines {
+		trimmed := strings.TrimSpace(line)
+		if trimmed == "" || strings.HasPrefix(trimmed, "//") || strings.HasPrefix(trimmed, "#") {
+			continue
+		}
+		if strings.Contains(trimmed, "{") || strings.Contains(trimmed, "}") || strings.Contains(trimmed, ";") || functionRe.MatchString(trimmed) {
+			hasCShape = true
+			break
+		}
+	}
+	if hasCShape || len(functions) > 0 {
+		return nil
+	}
+
+	for i, line := range lines {
+		trimmed := strings.TrimSpace(line)
+		if trimmed == "" {
+			continue
+		}
+		return &diagnostic{
+			File:     path,
+			Line:     i + 1,
+			Column:   firstNonSpaceColumn(line),
+			Severity: "error",
+			Message:  "syntax error",
+			ID:       "syntaxError",
+			Code:     line,
+		}
+	}
+	return nil
+}
+
+func nextMeaningfulLine(lines []string, start int) int {
+	for i := start; i < len(lines); i++ {
+		trimmed := strings.TrimSpace(lines[i])
+		if trimmed != "" && !strings.HasPrefix(trimmed, "//") {
+			return i
+		}
+	}
+	return -1
+}
+
+func isFunctionDefinition(lines []string, idx int, line string) bool {
+	if !functionRe.MatchString(line) {
+		return false
+	}
+	trimmed := strings.TrimSpace(line)
+	if strings.Contains(trimmed, "{") {
+		return true
+	}
+	next := nextMeaningfulLine(lines, idx+1)
+	return next >= 0 && strings.TrimSpace(lines[next]) == "{"
+}
+
+func collectInlineSuppressions(lines []string) []inlineSuppression {
+	var out []inlineSuppression
+	for i, line := range lines {
+		matches := inlineSupRe.FindAllStringSubmatch(line, -1)
+		for _, match := range matches {
+			target := nextMeaningfulLine(lines, i+1)
+			if target >= 0 {
+				out = append(out, inlineSuppression{
+					line: target + 1,
+					id:   match[1],
+				})
+			}
+		}
+	}
+	return out
+}
+
+func applyInlineSuppressions(diags []diagnostic, suppressions []inlineSuppression, enabled bool) []diagnostic {
+	if !enabled || len(suppressions) == 0 {
+		return diags
+	}
+	var out []diagnostic
+	for _, diag := range diags {
+		suppressed := false
+		for _, s := range suppressions {
+			if s.line == diag.Line && s.id == diag.ID {
+				suppressed = true
+				break
+			}
+		}
+		if !suppressed {
+			out = append(out, diag)
+		}
+	}
+	return out
+}
+
+func applySuppressions(diags []diagnostic, cfg config) []diagnostic {
+	if len(cfg.suppressions) == 0 {
+		return diags
+	}
+	var out []diagnostic
+	for _, diag := range diags {
+		suppressed := false
+		for _, sup := range cfg.suppressions {
+			if !sup.anyID && sup.id != diag.ID {
+				continue
+			}
+			if sup.hasFile && !matchPath(sup.file, diag.File) {
+				continue
+			}
+			if sup.hasLine && sup.line != diag.Line {
+				continue
+			}
+			suppressed = true
+			break
+		}
+		if !suppressed {
+			out = append(out, diag)
+		}
+	}
+	return out
+}
+
+func isNameReadLater(lines []string, name string, line int) bool {
+	pattern := regexp.MustCompile(`\b` + regexp.QuoteMeta(name) + `\b`)
+	for i := line; i < len(lines); i++ {
+		current := lines[i]
+		if i == line-1 {
+			declIdx := strings.Index(current, "=")
+			if declIdx >= 0 {
+				current = current[declIdx+1:]
+			}
+		}
+		if pattern.MatchString(current) {
+			return true
+		}
+	}
+	return false
+}
+
+func isArrayReadLater(lines []string, name string, line int) bool {
+	pattern := regexp.MustCompile(`\b` + regexp.QuoteMeta(name) + `\s*\[`)
+	for i := line; i < len(lines); i++ {
+		current := lines[i]
+		if i == line-1 {
+			assignIdx := strings.Index(current, "=")
+			if assignIdx >= 0 {
+				current = current[assignIdx+1:]
+			}
+		}
+		if pattern.MatchString(current) {
+			return true
+		}
+	}
+	return false
+}
+
+func writeTextDiagnostics(w io.Writer, diags []diagnostic, cfg config) {
+	for _, diag := range diags {
+		_, _ = io.WriteString(w, formatTextDiagnostic(diag, cfg))
+	}
+}
+
+func formatTextDiagnostic(diag diagnostic, cfg config) string {
+	if cfg.template != "" {
+		return formatTemplateDiagnostic(diag, cfg.template, cfg.templateLocation)
+	}
+
+	severity := diag.Severity
+	if diag.File == "nofile" {
+		return fmt.Sprintf("%s:%d:%d: %s: %s [%s]\n", diag.File, diag.Line, diag.Column, severity, diag.Message, diag.ID)
+	}
+
+	return formatSnippetDiagnostic(diag, severity)
+}
+
+func formatSnippetDiagnostic(diag diagnostic, severity string) string {
+	var b strings.Builder
+	_, _ = fmt.Fprintf(&b, "%s:%d:%d: %s: %s [%s]\n", diag.File, diag.Line, diag.Column, severity, diag.Message, diag.ID)
+	if !diag.NoSnippet && diag.Code != "" {
+		b.WriteString(diag.Code)
+		b.WriteByte('\n')
+		if diag.Column > 1 {
+			b.WriteString(strings.Repeat(" ", diag.Column-1))
+		}
+		b.WriteString("^\n")
+	}
+	return b.String()
+}
+
+func formatTemplateDiagnostic(diag diagnostic, template, locationTemplate string) string {
+	switch template {
+	case "gcc":
+		return formatSnippetDiagnostic(diag, "warning")
+	case "cppcheck1":
+		return fmt.Sprintf("[%s:%d]: (%s) %s\n", diag.File, diag.Line, diag.Severity, diag.Message)
+	case "vs":
+		return fmt.Sprintf("%s(%d): %s: %s\n", diag.File, diag.Line, diag.Severity, diag.Message)
+	case "edit":
+		return fmt.Sprintf("%s +%d: %s: %s\n", diag.File, diag.Line, diag.Severity, diag.Message)
+	default:
+		expanded := expandTemplate(template, diag, diag.Severity)
+		if !strings.HasSuffix(expanded, "\n") {
+			expanded += "\n"
+		}
+		if locationTemplate != "" && diag.Info != "" {
+			loc := expandLocationTemplate(locationTemplate, diag)
+			expanded += loc
+			if !strings.HasSuffix(expanded, "\n") {
+				expanded += "\n"
+			}
+		}
+		return expanded
+	}
+}
+
+func expandTemplate(template string, diag diagnostic, severity string) string {
+	out := decodeEscapes(template)
+	callstack := ""
+	if diag.File != "" && diag.File != "nofile" {
+		callstack = fmt.Sprintf("[%s:%d]", diag.File, diag.Line)
+	}
+
+	replacements := map[string]string{
+		"{file}":     diag.File,
+		"{line}":     strconv.Itoa(diag.Line),
+		"{column}":   strconv.Itoa(diag.Column),
+		"{callstack}": callstack,
+		"{severity}": severity,
+		"{message}":  diag.Message,
+		"{id}":       diag.ID,
+		"{cwe}":      diag.CWE,
+		"{code}":     diag.Code,
+	}
+	for key, value := range replacements {
+		out = strings.ReplaceAll(out, key, value)
+	}
+
+	for {
+		start := strings.Index(out, "{inconclusive:")
+		if start < 0 {
+			break
+		}
+		end := strings.Index(out[start:], "}")
+		if end < 0 {
+			break
+		}
+		out = out[:start] + out[start+end+1:]
+	}
+
+	return out
+}
+
+func expandLocationTemplate(template string, diag diagnostic) string {
+	out := decodeEscapes(template)
+	replacements := map[string]string{
+		"{file}":   diag.File,
+		"{line}":   strconv.Itoa(diag.Line),
+		"{column}": strconv.Itoa(diag.Column),
+		"{info}":   diag.Info,
+		"{code}":   diag.Code,
+	}
+	for key, value := range replacements {
+		out = strings.ReplaceAll(out, key, value)
+	}
+	return out
+}
+
+func decodeEscapes(s string) string {
+	replacer := strings.NewReplacer(`\t`, "\t", `\n`, "\n", `\r`, "\r")
+	return replacer.Replace(s)
+}
+
+func writeXML(w io.Writer, diags []diagnostic) {
+	results := xmlResults{
+		Version: "2",
+		Cppcheck: xmlCppcheck{
+			Version: strings.TrimSpace(versionText[len("Cppcheck "):]),
+		},
+	}
+
+	for _, diag := range diags {
+		item := xmlError{
+			ID:       diag.ID,
+			Severity: diag.Severity,
+			Msg:      diag.Message,
+			Verbose:  diag.Message,
+			CWE:      diag.CWE,
+		}
+		if diag.File != "" && diag.File != "nofile" && !diag.OmitFile0 {
+			item.File0 = diag.File
+		}
+		if diag.File != "" && diag.File != "nofile" {
+			item.Location = &xmlLocation{
+				File:   diag.File,
+				Line:   diag.Line,
+				Column: diag.Column,
+				Info:   diag.Info,
+			}
+		}
+		if diag.Symbol != "" {
+			s := diag.Symbol
+			item.Symbol = &s
+		}
+		results.Errors = append(results.Errors, item)
+	}
+
+	body, _ := xml.MarshalIndent(results, "", "    ")
+	_, _ = io.WriteString(w, xml.Header)
+	_, _ = w.Write(body)
+	_, _ = io.WriteString(w, "\n")
+}
+
+func writeSARIF(w io.Writer, diags []diagnostic) {
+	log := sarifLog{
+		Version: "2.1.0",
+		Schema:  "https://json.schemastore.org/sarif-2.1.0.json",
+		Runs: []sarifRun{{
+			Tool: sarifTool{
+				Driver: sarifDriver{
+					Name:    "Cppcheck",
+					Version: strings.TrimSpace(strings.TrimPrefix(versionText, "Cppcheck ")),
+				},
+			},
+		}},
+	}
+
+	for _, diag := range diags {
+		result := sarifResult{
+			RuleID: diag.ID,
+			Level:  sarifLevel(diag.Severity),
+			Message: sarifMessage{
+				Text: diag.Message,
+			},
+		}
+		if diag.File != "" && diag.File != "nofile" {
+			result.Locations = []sarifLocation{{
+				PhysicalLocation: sarifPhysicalLocation{
+					ArtifactLocation: sarifArtifactLocation{URI: diag.File},
+					Region: sarifRegion{
+						StartLine:   diag.Line,
+						StartColumn: diag.Column,
+					},
+				},
+			}}
+		}
+		log.Runs[0].Results = append(log.Runs[0].Results, result)
+	}
+
+	encoded, _ := json.MarshalIndent(log, "", "  ")
+	_, _ = w.Write(encoded)
+	_, _ = io.WriteString(w, "\n")
+}
+
+func sarifLevel(severity string) string {
+	switch severity {
+	case "error":
+		return "error"
+	case "style":
+		return "warning"
+	default:
+		return "note"
+	}
+}
+
+func isXMLFormat(format string) bool {
+	return format == "xml"
+}
+
+func firstNonSpaceColumn(line string) int {
+	for i, r := range line {
+		if r != ' ' && r != '\t' {
+			return i + 1
+		}
+	}
+	return 1
+}
+
+func matchPath(pattern, path string) bool {
+	if pattern == "" {
+		return false
+	}
+	if ok, err := filepath.Match(pattern, path); err == nil && ok {
+		return true
+	}
+	base := filepath.Base(path)
+	if ok, err := filepath.Match(pattern, base); err == nil && ok {
+		return true
+	}
+	return strings.Contains(path, pattern)
+}
