	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

//go:embed help.txt
var helpText string

const versionText = "Cppcheck 2.19 dev\n"

var (
	arrayDeclRe = regexp.MustCompile(`^\s*(?:static\s+)?(?:const\s+)?[A-Za-z_][\w:<>]*\s+([A-Za-z_]\w*)\s*\[(\d+)\]\s*(=\s*\{[^;]*\})?\s*;`)
	scalarInitRe = regexp.MustCompile(`^\s*(?:static\s+)?(?:const\s+)?[A-Za-z_][\w:<>]*\s+([A-Za-z_]\w*)\s*=\s*([^;]+);`)
	functionRe   = regexp.MustCompile(`^\s*(?:static\s+)?[A-Za-z_][\w:<>]*\s+([A-Za-z_]\w*)\s*\([^;]*\)\s*\{?\s*$`)
	arrayUseRe   = regexp.MustCompile(`\b([A-Za-z_]\w*)\s*\[(\d+)\]`)
	funcCallRe   = regexp.MustCompile(`\b([A-Za-z_]\w*)\s*\(`)
	inlineSupRe  = regexp.MustCompile(`cppcheck-suppress\s+([A-Za-z_][\w]*)`)
)

var sourceExtensions = map[string]bool{
	".c":   true,
	".cc":  true,
	".cpp": true,
	".cxx": true,
	".c++": true,
	".ipp": true,
	".ixx": true,
	".tpp": true,
	".txx": true,
}

var cppExtensions = map[string]bool{
	".cc":  true,
	".cpp": true,
	".cxx": true,
	".c++": true,
	".ipp": true,
	".ixx": true,
	".tpp": true,
	".txx": true,
}

type config struct {
	quiet             bool
	outputFormat      string
	outputFile        string
	template          string
	templateLocation  string
	errorExitCode     int
	hasErrorExitCode  bool
	enableStyle       bool
	enableUnusedFunc  bool
	enableAll         bool
	inlineSuppress    bool
	language          string
	ignorePatterns    []string
	fileFilters       []string
	fileLists         []string
	suppressions      []suppression
	checkersReportOut string
}

type suppression struct {
	id         string
	file       string
	line       int
	anyID      bool
	hasLine    bool
	hasFile    bool
}

type inputFile struct {
	displayPath string
	realPath    string
	size        int64
	language    string
}

type diagnostic struct {
	File       string
	Line       int
	Column     int
	Severity   string
	Message    string
	ID         string
	CWE        string
	Info       string
	Symbol     string
	Code       string
	NoSnippet  bool
	OmitFile0  bool
}

type arrayDecl struct {
	name        string
	size        int
	line        int
	column      int
	initialized bool
	code        string
}

type scalarDecl struct {
	name       string
	line       int
	assignCol  int
	code       string
	usedLater  bool
}

type functionDecl struct {
	name   string
	line   int
	column int
}

type inlineSuppression struct {
	line int
	id   string
}

type xmlResults struct {
	XMLName  xml.Name    `xml:"results"`
	Version  string      `xml:"version,attr"`
	Cppcheck xmlCppcheck `xml:"cppcheck"`
	Errors   []xmlError  `xml:"errors>error"`
}

type xmlCppcheck struct {
	Version string `xml:"version,attr"`
}

type xmlError struct {
	ID       string        `xml:"id,attr"`
	Severity string        `xml:"severity,attr"`
	Msg      string        `xml:"msg,attr"`
	Verbose  string        `xml:"verbose,attr"`
	CWE      string        `xml:"cwe,attr,omitempty"`
	File0    string        `xml:"file0,attr,omitempty"`
	Location *xmlLocation  `xml:"location,omitempty"`
	Symbol   *string       `xml:"symbol,omitempty"`
}

type xmlLocation struct {
	File   string `xml:"file,attr"`
	Line   int    `xml:"line,attr"`
	Column int    `xml:"column,attr"`
	Info   string `xml:"info,attr,omitempty"`
}

type sarifLog struct {
	Version string     `json:"version"`
	Schema  string     `json:"$schema"`
	Runs    []sarifRun `json:"runs"`
}

type sarifRun struct {
	Tool    sarifTool     `json:"tool"`
	Results []sarifResult `json:"results"`
}

type sarifTool struct {
	Driver sarifDriver `json:"driver"`
}

type sarifDriver struct {
	Name    string `json:"name"`
	Version string `json:"version"`
}

type sarifResult struct {
	RuleID   string             `json:"ruleId"`
	Level    string             `json:"level"`
	Message  sarifMessage       `json:"message"`
	Locations []sarifLocation   `json:"locations,omitempty"`
}

type sarifMessage struct {
	Text string `json:"text"`
}

type sarifLocation struct {
	PhysicalLocation sarifPhysicalLocation `json:"physicalLocation"`
}

type sarifPhysicalLocation struct {
	ArtifactLocation sarifArtifactLocation `json:"artifactLocation"`
	Region           sarifRegion           `json:"region"`
}

type sarifArtifactLocation struct {
	URI string `json:"uri"`
}

type sarifRegion struct {
	StartLine   int `json:"startLine,omitempty"`
	StartColumn int `json:"startColumn,omitempty"`
}

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

func run(args []string, stdout, stderr io.Writer) int {
	if len(args) == 0 {
		_, _ = io.WriteString(stdout, helpText)
		return 0
	}

	for _, arg := range args {
		if arg == "-h" || arg == "--help" {
			_, _ = io.WriteString(stdout, helpText)
			return 0
		}
	}
	for _, arg := range args {
		if arg == "--version" {
			_, _ = io.WriteString(stdout, versionText)
			return 0
		}
	}

	cfg, pathArgs, err := parseArgs(args)
	if err != nil {
		_, _ = fmt.Fprintf(stdout, "cppcheck: error: %s.\n", err.Error())
		return 1
	}

	if len(pathArgs) == 0 && len(cfg.fileLists) == 0 {
		_, _ = io.WriteString(stdout, "cppcheck: error: no C or C++ source files found.\n")
		return 1
	}

	fileListArgs, err := expandFileLists(cfg.fileLists)
	if err != nil {
		_, _ = fmt.Fprintf(stdout, "cppcheck: error: %s.\n", err.Error())
		return 1
	}

	allArgs := append([]string{}, pathArgs...)
	allArgs = append(allArgs, fileListArgs...)

	inputs := expandInputs(allArgs, cfg)
	if len(inputs) == 0 {
		_, _ = io.WriteString(stdout, "cppcheck: error: could not find or open any of the paths given.\n")
		return 1
	}

	totalBytes := int64(0)
	anyCpp := false
	for _, input := range inputs {
		totalBytes += input.size
		if input.language == "c++" {
			anyCpp = true
		}
	}

	diagWriter := io.Writer(stderr)
	var closeFn func() error
	if cfg.outputFile != "" {
		f, createErr := os.Create(cfg.outputFile)
		if createErr != nil {
			_, _ = fmt.Fprintf(stdout, "cppcheck: error: %s.\n", createErr.Error())
			return 1
		}
		diagWriter = f
		closeFn = f.Close
	}
	if closeFn != nil {
		defer closeFn()
	}

	totalFiles := len(inputs)
	cumulativeBytes := int64(0)
	allDiags := make([]diagnostic, 0, 8)
	anyNonInfo := false

	for idx, input := range inputs {
		if !cfg.quiet {
			_, _ = fmt.Fprintf(stdout, "Checking %s ...\n", input.displayPath)
		}

		fileDiags := analyzeFile(input, cfg)
		fileDiags = applySuppressions(fileDiags, cfg)
		for _, diag := range fileDiags {
			if diag.Severity != "information" {
				anyNonInfo = true
			}
		}

		if isXMLFormat(cfg.outputFormat) || cfg.outputFormat == "sarif" {
			allDiags = append(allDiags, fileDiags...)
		} else {
			writeTextDiagnostics(diagWriter, fileDiags, cfg)
		}

		cumulativeBytes += input.size
		if !cfg.quiet && totalFiles > 1 {
			percent := 100
			if totalBytes > 0 {
				percent = int((cumulativeBytes * 100) / totalBytes)
			}
			_, _ = fmt.Fprintf(stdout, "%d/%d files checked %d%% done\n", idx+1, totalFiles, percent)
		}
	}

	if cfg.enableAll {
		checkerCount := "113/186"
		if anyCpp || cfg.language == "c++" {
			checkerCount = "173/186"
		}
		infoDiag := diagnostic{
			File:      "nofile",
			Line:      0,
			Column:    0,
			Severity:  "information",
			Message:   fmt.Sprintf("Active checkers: %s (use --checkers-report=<filename> to see details)", checkerCount),
			ID:        "checkersReport",
			NoSnippet: true,
		}
		if isXMLFormat(cfg.outputFormat) || cfg.outputFormat == "sarif" {
			allDiags = append(allDiags, infoDiag)
		} else {
			writeTextDiagnostics(diagWriter, []diagnostic{infoDiag}, cfg)
		}
	}

	if isXMLFormat(cfg.outputFormat) {
		writeXML(diagWriter, allDiags)
	} else if cfg.outputFormat == "sarif" {
		writeSARIF(diagWriter, allDiags)
	}

	if cfg.checkersReportOut != "" {
		_ = os.WriteFile(cfg.checkersReportOut, []byte("Active checkers report is not available in this reimplementation.\n"), 0644)
	}

	if cfg.hasErrorExitCode && anyNonInfo {
		return cfg.errorExitCode
	}
	return 0
}

func parseArgs(args []string) (config, []string, error) {
	cfg := config{outputFormat: "text"}
	var paths []string

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if !strings.HasPrefix(arg, "-") || arg == "-" {
			paths = append(paths, arg)
			continue
		}

		switch {
		case arg == "-q" || arg == "--quiet":
			cfg.quiet = true
		case arg == "--xml":
			cfg.outputFormat = "xml"
		case arg == "--inline-suppr":
			cfg.inlineSuppress = true
		case arg == "-f" || arg == "--force" || arg == "--inconclusive" || arg == "--check-config" || arg == "--check-library" || arg == "--dump" || arg == "-E" || arg == "--fsigned-char" || arg == "--funsigned-char" || arg == "--report-progress" || arg == "--safety" || arg == "-v" || arg == "--verbose":
			// Recognized no-op options.
		case arg == "-j" || arg == "-l" || arg == "-I" || arg == "-i" || arg == "-x":
			if i+1 >= len(args) {
				return cfg, nil, fmt.Errorf("unrecognized command line option: %q", arg)
			}
			val := args[i+1]
			i++
			switch arg {
			case "-i":
				cfg.ignorePatterns = append(cfg.ignorePatterns, val)
			case "-x":
				cfg.language = val
			}
		case strings.HasPrefix(arg, "-D") || strings.HasPrefix(arg, "-U") || strings.HasPrefix(arg, "-rp="):
			// Recognized no-op options.
		case arg == "--output-file":
			if i+1 >= len(args) {
				return cfg, nil, fmt.Errorf("unrecognized command line option: %q", arg)
			}
			cfg.outputFile = args[i+1]
			i++
		case strings.HasPrefix(arg, "--output-file="):
			cfg.outputFile = strings.TrimPrefix(arg, "--output-file=")
		case arg == "--template":
			if i+1 >= len(args) {
				return cfg, nil, fmt.Errorf("unrecognized command line option: %q", arg)
			}
			cfg.template = args[i+1]
			i++
		case strings.HasPrefix(arg, "--template="):
			cfg.template = strings.TrimPrefix(arg, "--template=")
		case arg == "--template-location":
			if i+1 >= len(args) {
				return cfg, nil, fmt.Errorf("unrecognized command line option: %q", arg)
			}
			cfg.templateLocation = args[i+1]
			i++
		case strings.HasPrefix(arg, "--template-location="):
			cfg.templateLocation = strings.TrimPrefix(arg, "--template-location=")
		case strings.HasPrefix(arg, "--output-format="):
			format := strings.TrimPrefix(arg, "--output-format=")
			cfg.outputFormat = normalizeOutputFormat(format)
		case arg == "--output-format":
			if i+1 >= len(args) {
				return cfg, nil, fmt.Errorf("unrecognized command line option: %q", arg)
			}
			cfg.outputFormat = normalizeOutputFormat(args[i+1])
			i++
		case strings.HasPrefix(arg, "--error-exitcode="):
			n, parseErr := strconv.Atoi(strings.TrimPrefix(arg, "--error-exitcode="))
			if parseErr != nil {
				return cfg, nil, fmt.Errorf("unrecognized command line option: %q", arg)
			}
			cfg.errorExitCode = n
			cfg.hasErrorExitCode = true
		case arg == "--error-exitcode":
			if i+1 >= len(args) {
				return cfg, nil, fmt.Errorf("unrecognized command line option: %q", arg)
			}
			n, parseErr := strconv.Atoi(args[i+1])
			if parseErr != nil {
				return cfg, nil, fmt.Errorf("unrecognized command line option: %q", arg)
			}
			cfg.errorExitCode = n
			cfg.hasErrorExitCode = true
			i++
		case strings.HasPrefix(arg, "--enable="):
			parseEnable(strings.TrimPrefix(arg, "--enable="), &cfg)
		case arg == "--enable":
			if i+1 >= len(args) {
				return cfg, nil, fmt.Errorf("unrecognized command line option: %q", arg)
			}
			parseEnable(args[i+1], &cfg)
			i++
		case strings.HasPrefix(arg, "--language="):
			cfg.language = strings.TrimPrefix(arg, "--language=")
		case arg == "--language":
			if i+1 >= len(args) {
				return cfg, nil, fmt.Errorf("unrecognized command line option: %q", arg)
			}
			cfg.language = args[i+1]
			i++
		case strings.HasPrefix(arg, "--file-list="):
			cfg.fileLists = append(cfg.fileLists, strings.TrimPrefix(arg, "--file-list="))
		case arg == "--file-list":
			if i+1 >= len(args) {
				return cfg, nil, fmt.Errorf("unrecognized command line option: %q", arg)
			}
			cfg.fileLists = append(cfg.fileLists, args[i+1])
			i++
		case strings.HasPrefix(arg, "--file-filter="):
			cfg.fileFilters = append(cfg.fileFilters, strings.TrimPrefix(arg, "--file-filter="))
		case arg == "--file-filter":
			if i+1 >= len(args) {
				return cfg, nil, fmt.Errorf("unrecognized command line option: %q", arg)
			}
			cfg.fileFilters = append(cfg.fileFilters, args[i+1])
			i++
		case strings.HasPrefix(arg, "--suppress="):
			cfg.suppressions = append(cfg.suppressions, parseSuppression(strings.TrimPrefix(arg, "--suppress=")))
		case arg == "--suppress":
			if i+1 >= len(args) {
				return cfg, nil, fmt.Errorf("unrecognized command line option: %q", arg)
			}
			cfg.suppressions = append(cfg.suppressions, parseSuppression(args[i+1]))
			i++
		case strings.HasPrefix(arg, "--suppressions-list="):
			specs, readErr := readSuppressionList(strings.TrimPrefix(arg, "--suppressions-list="))
			if readErr != nil {
				return cfg, nil, readErr
			}
			cfg.suppressions = append(cfg.suppressions, specs...)
		case strings.HasPrefix(arg, "--checkers-report="):
			cfg.checkersReportOut = strings.TrimPrefix(arg, "--checkers-report=")
		case arg == "--checkers-report":
			if i+1 >= len(args) {
				return cfg, nil, fmt.Errorf("unrecognized command line option: %q", arg)
			}
			cfg.checkersReportOut = args[i+1]
			i++
		case strings.HasPrefix(arg, "--ignore="):
			cfg.ignorePatterns = append(cfg.ignorePatterns, strings.TrimPrefix(arg, "--ignore="))
		case isRecognizedLongOption(arg):
			// Recognized no-op options.
		default:
			return cfg, nil, fmt.Errorf("unrecognized command line option: %q", arg)
		}
	}

	return cfg, paths, nil
}

func parseEnable(value string, cfg *config) {
	for _, part := range strings.Split(value, ",") {
		switch strings.TrimSpace(part) {
		case "style":
			cfg.enableStyle = true
		case "unusedFunction":
			cfg.enableUnusedFunc = true
		case "all":
			cfg.enableAll = true
			cfg.enableStyle = true
			cfg.enableUnusedFunc = true
		}
	}
}

func normalizeOutputFormat(v string) string {
	switch v {
	case "xml", "xmlv2", "xmlv3":
		return "xml"
	case "sarif":
		return "sarif"
	default:
		return "text"
	}
}

func isRecognizedLongOption(arg string) bool {
	prefixes := []string{
		"--addon=", "--addon-python=", "--cppcheck-build-dir=", "--check-level=", "--config-exclude=", "--config-excludes-file=", "--disable=",
		"--exitcode-suppressions=", "--includes-file=", "--include=", "--library=", "--max-configs=", "--max-ctu-depth=", "--platform=",
		"--plist-output=", "--project=", "--project-configuration=", "--report-type=", "--rule=", "--rule-file=", "--showtime=", "--std=",
		"--suppress-xml=",
	}
	if arg == "--errorlist" {
		return true
	}
	for _, prefix := range prefixes {
		if strings.HasPrefix(arg, prefix) {
			return true
		}
	}
	return false
}

func parseSuppression(spec string) suppression {
	parts := strings.Split(spec, ":")
	s := suppression{id: parts[0]}
	if parts[0] == "*" {
		s.anyID = true
	}
	if len(parts) > 1 && parts[1] != "" {
		s.file = parts[1]
		s.hasFile = true
	}
	if len(parts) > 2 && parts[2] != "" {
		if n, err := strconv.Atoi(parts[2]); err == nil {
			s.line = n
			s.hasLine = true
		}
	}
	return s
}

func readSuppressionList(path string) ([]suppression, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	var out []suppression
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		out = append(out, parseSuppression(line))
	}
	return out, scanner.Err()
}

func expandFileLists(paths []string) ([]string, error) {
	var out []string
	for _, path := range paths {
		f, err := os.Open(path)
		if err != nil {
			return nil, err
		}
		scanner := bufio.NewScanner(f)
		for scanner.Scan() {
			line := strings.TrimSpace(scanner.Text())
			if line != "" {
				out = append(out, line)
			}
		}
		closeErr := f.Close()
		if err := scanner.Err(); err != nil {
			return nil, err
		}
		if closeErr != nil {
			return nil, closeErr
		}
	}
	return out, nil
}

func expandInputs(args []string, cfg config) []inputFile {
	var out []inputFile
	for _, arg := range args {
		info, err := os.Stat(arg)
		if err != nil {
			continue
		}
		if info.IsDir() {
			root := arg
			var files []inputFile
			_ = filepath.WalkDir(root, func(path string, entry fs.DirEntry, walkErr error) error {
				if walkErr != nil || entry.IsDir() {
					return nil
				}
				if !sourceExtensions[strings.ToLower(filepath.Ext(path))] {
					return nil
				}
				rel, relErr := filepath.Rel(root, path)
				if relErr != nil {
					return nil
				}
				display := filepath.ToSlash(filepath.Join(root, rel))
				fileInfo, statErr := entry.Info()
				if statErr != nil {
					return nil
				}
				input := inputFile{
					displayPath: display,
					realPath:    path,
					size:        fileInfo.Size(),
					language:    detectLanguage(display, cfg.language),
				}
				if shouldIncludeInput(input, cfg) {
					files = append(files, input)
				}
				return nil
			})
			sort.Slice(files, func(i, j int) bool {
				return files[i].displayPath < files[j].displayPath
			})
			out = append(out, files...)
			continue
		}
		input := inputFile{
			displayPath: filepath.ToSlash(arg),
			realPath:    arg,
			size:        info.Size(),
			language:    detectLanguage(arg, cfg.language),
		}
		if shouldIncludeInput(input, cfg) {
			out = append(out, input)
		}
	}
	return out
}

func shouldIncludeInput(input inputFile, cfg config) bool {
	for _, pattern := range cfg.ignorePatterns {
		if matchPath(pattern, input.displayPath) {
			return false
		}
	}
	if len(cfg.fileFilters) == 0 {
		return true
	}
	for _, pattern := range cfg.fileFilters {
		if pattern == "" || pattern == "-" || pattern == "+" {
			continue
		}
		if matchPath(pattern, input.displayPath) {
			return true
		}
	}
	return false
}

func detectLanguage(path, forced string) string {
	if forced == "c" || forced == "c++" {
		return forced
	}
	if cppExtensions[strings.ToLower(filepath.Ext(path))] {
		return "c++"
	}
	return "c"
}

func analyzeFile(input inputFile, cfg config) []diagnostic {
	data, err := os.ReadFile(input.realPath)
	if err != nil {
		return nil
	}

	text := strings.ReplaceAll(string(data), "\r\n", "\n")
	lines := strings.Split(text, "\n")
	inlineSuppressions := collectInlineSuppressions(lines)

	arrays := map[string]arrayDecl{}
	scalars := map[string]scalarDecl{}
	functions := map[string]functionDecl{}

	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") || strings.HasPrefix(trimmed, "//") {
			continue
		}

		if m := arrayDeclRe.FindStringSubmatch(line); m != nil {
			name := m[1]
			size, _ := strconv.Atoi(m[2])
			arrays[name] = arrayDecl{
				name:        name,
				size:        size,
				line:        i + 1,
				column:      strings.Index(line, name) + 1,
				initialized: strings.TrimSpace(m[3]) != "",
				code:        line,
			}
			continue
		}

		if m := scalarInitRe.FindStringSubmatch(line); m != nil {
			name := m[1]
			scalars[name] = scalarDecl{
				name:      name,
				line:      i + 1,
				assignCol: strings.Index(line, "=") + 1,
				code:      line,
			}
			continue
		}

		if isFunctionDefinition(lines, i, line) {
			if m := functionRe.FindStringSubmatch(line); m != nil {
				name := m[1]
				functions[name] = functionDecl{
					name:   name,
					line:   i + 1,
					column: strings.Index(line, name) + 1,
				}
			}
		}
	}

	if diag := detectSyntaxError(input.displayPath, lines, functions); diag != nil {
		return applyInlineSuppressions([]diagnostic{*diag}, inlineSuppressions, cfg.inlineSuppress)
	}

	var diags []diagnostic
	emittedUninit := map[string]bool{}
	emittedConst := map[string]bool{}
	emittedUnassigned := map[string]bool{}

	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "//") {
			continue
		}
		if arrayDeclRe.MatchString(line) {
			continue
		}

		matches := arrayUseRe.FindAllStringSubmatchIndex(line, -1)
		for _, match := range matches {
			name := line[match[2]:match[3]]
			indexText := line[match[4]:match[5]]
			index, _ := strconv.Atoi(indexText)
			decl, ok := arrays[name]
			if !ok {
				continue
			}

			if index >= decl.size {
				diags = append(diags, diagnostic{
					File:     input.displayPath,
					Line:     i + 1,
					Column:   match[0] + strings.Index(line[match[0]:match[1]], "[") + 1,
					Severity: "error",
					Message:  fmt.Sprintf("Array '%s[%d]' accessed at index %d, which is out of bounds.", name, decl.size, index),
					ID:       "arrayIndexOutOfBounds",
					CWE:      "788",
					Info:     "Array index out of bounds",
					Code:     line,
				})
			}

			if !decl.initialized && !emittedUninit[name] {
				if cfg.enableAll && !emittedConst[name] {
					diags = append(diags, diagnostic{
						File:     input.displayPath,
						Line:     decl.line,
						Column:   decl.column,
						Severity: "style",
						Message:  fmt.Sprintf("Variable '%s' can be declared as const array", name),
						ID:       "constVariable",
						CWE:      "398",
						Info:     fmt.Sprintf("Variable '%s' can be declared as const array", name),
						Symbol:   name,
						Code:     decl.code,
					})
					emittedConst[name] = true
				}

				diags = append(diags, diagnostic{
					File:     input.displayPath,
					Line:     i + 1,
					Column:   match[0] + 1,
					Severity: "error",
					Message:  fmt.Sprintf("Uninitialized variable: %s", name),
					ID:       "uninitvar",
					CWE:      "457",
					Symbol:   name,
					Code:     line,
				})
				emittedUninit[name] = true

				if cfg.enableAll && !emittedUnassigned[name] {
					diags = append(diags, diagnostic{
						File:     input.displayPath,
						Line:     decl.line,
						Column:   decl.column,
						Severity: "style",
						Message:  fmt.Sprintf("Variable '%s' is not assigned a value.", name),
						ID:       "unassignedVariable",
						CWE:      "665",
						Symbol:   name,
						Code:     decl.code,
					})
					emittedUnassigned[name] = true
				}
			}
		}
	}

	if cfg.enableStyle {
		for _, scalar := range scalars {
			if !isNameReadLater(lines, scalar.name, scalar.line) {
				diags = append(diags, diagnostic{
					File:     input.displayPath,
					Line:     scalar.line,
					Column:   scalar.assignCol,
					Severity: "style",
					Message:  fmt.Sprintf("Variable '%s' is assigned a value that is never used.", scalar.name),
					ID:       "unreadVariable",
					CWE:      "563",
					Symbol:   scalar.name,
					Code:     scalar.code,
				})
			}
		}

		for i, line := range lines {
			if m := regexp.MustCompile(`\b([A-Za-z_]\w*)\s*(\[\d+\])\s*=\s*[^;]+;`).FindStringSubmatch(line); m != nil {
				name := m[1]
				if _, ok := arrays[name]; !ok {
					continue
				}
				target := name + m[2]
				if !isArrayReadLater(lines, name, i+1) {
					diags = append(diags, diagnostic{
						File:     input.displayPath,
						Line:     i + 1,
						Column:   strings.Index(line, "=") + 1,
						Severity: "style",
						Message:  fmt.Sprintf("Variable '%s' is assigned a value that is never used.", target),
						ID:       "unreadVariable",
						CWE:      "563",
						Symbol:   target,
						Code:     line,
					})
				}
			}
		}
	}

	if cfg.enableUnusedFunc {
		used := map[string]bool{}
		for i, line := range lines {
			matches := funcCallRe.FindAllStringSubmatchIndex(line, -1)
			for _, match := range matches {
				name := line[match[2]:match[3]]
				if fn, ok := functions[name]; ok {
					if fn.line == i+1 && isFunctionDefinition(lines, i, line) {
						continue
					}
				}
				used[name] = true
			}
		}
		var names []string
		for name := range functions {
			names = append(names, name)
		}
		sort.Strings(names)
		for _, name := range names {
			fn := functions[name]
			if name == "main" || used[name] {
				continue
			}
			diags = append(diags, diagnostic{
				File:     input.displayPath,
				Line:     fn.line,
				Column:   fn.column,
				Severity: "style",
				Message:  fmt.Sprintf("The function '%s' is never used.", name),
				ID:       "unusedFunction",
				CWE:      "561",
				Symbol:   name,
				Code:     lines[fn.line-1],
				OmitFile0: true,
			})
		}
	}

	return applyInlineSuppressions(diags, inlineSuppressions, cfg.inlineSuppress)
}

func detectSyntaxError(path string, lines []string, functions map[string]functionDecl) *diagnostic {
	for i := 0; i < len(lines)-1; i++ {
		current := strings.TrimSpace(lines[i])
		if current == "" || strings.HasPrefix(current, "//") {
			continue
		}
		if strings.HasSuffix(current, ";") || strings.HasSuffix(current, "{") || strings.HasSuffix(current, "}") || strings.HasSuffix(current, ":") {
			continue
		}

		nextIndex := nextMeaningfulLine(lines, i+1)
		if nextIndex < 0 {
			break
		}
		next := strings.TrimSpace(lines[nextIndex])
		if strings.HasPrefix(next, "return") {
			tokens := strings.Fields(current)
			last := ""
			if len(tokens) > 0 {
				last = tokens[len(tokens)-1]
			}
			msg := "syntax error"
			if last != "" {
				msg = fmt.Sprintf("syntax error: %s return", last)
			}
			col := firstNonSpaceColumn(lines[nextIndex])
			return &diagnostic{
				File:     path,
				Line:     nextIndex + 1,
				Column:   col,
				Severity: "error",
				Message:  msg,
				ID:       "syntaxError",
				Code:     lines[nextIndex],
			}
		}
	}

	hasCShape := false
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "//") || strings.HasPrefix(trimmed, "#") {
			continue
		}
		if strings.Contains(trimmed, "{") || strings.Contains(trimmed, "}") || strings.Contains(trimmed, ";") || functionRe.MatchString(trimmed) {
			hasCShape = true
			break
		}
	}
	if hasCShape || len(functions) > 0 {
		return nil
	}

	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}
		return &diagnostic{
			File:     path,
			Line:     i + 1,
			Column:   firstNonSpaceColumn(line),
			Severity: "error",
			Message:  "syntax error",
			ID:       "syntaxError",
			Code:     line,
		}
	}
	return nil
}

func nextMeaningfulLine(lines []string, start int) int {
	for i := start; i < len(lines); i++ {
		trimmed := strings.TrimSpace(lines[i])
		if trimmed != "" && !strings.HasPrefix(trimmed, "//") {
			return i
		}
	}
	return -1
}

func isFunctionDefinition(lines []string, idx int, line string) bool {
	if !functionRe.MatchString(line) {
		return false
	}
	trimmed := strings.TrimSpace(line)
	if strings.Contains(trimmed, "{") {
		return true
	}
	next := nextMeaningfulLine(lines, idx+1)
	return next >= 0 && strings.TrimSpace(lines[next]) == "{"
}

func collectInlineSuppressions(lines []string) []inlineSuppression {
	var out []inlineSuppression
	for i, line := range lines {
		matches := inlineSupRe.FindAllStringSubmatch(line, -1)
		for _, match := range matches {
			target := nextMeaningfulLine(lines, i+1)
			if target >= 0 {
				out = append(out, inlineSuppression{
					line: target + 1,
					id:   match[1],
				})
			}
		}
	}
	return out
}

func applyInlineSuppressions(diags []diagnostic, suppressions []inlineSuppression, enabled bool) []diagnostic {
	if !enabled || len(suppressions) == 0 {
		return diags
	}
	var out []diagnostic
	for _, diag := range diags {
		suppressed := false
		for _, s := range suppressions {
			if s.line == diag.Line && s.id == diag.ID {
				suppressed = true
				break
			}
		}
		if !suppressed {
			out = append(out, diag)
		}
	}
	return out
}

func applySuppressions(diags []diagnostic, cfg config) []diagnostic {
	if len(cfg.suppressions) == 0 {
		return diags
	}
	var out []diagnostic
	for _, diag := range diags {
		suppressed := false
		for _, sup := range cfg.suppressions {
			if !sup.anyID && sup.id != diag.ID {
				continue
			}
			if sup.hasFile && !matchPath(sup.file, diag.File) {
				continue
			}
			if sup.hasLine && sup.line != diag.Line {
				continue
			}
			suppressed = true
			break
		}
		if !suppressed {
			out = append(out, diag)
		}
	}
	return out
}

func isNameReadLater(lines []string, name string, line int) bool {
	pattern := regexp.MustCompile(`\b` + regexp.QuoteMeta(name) + `\b`)
	for i := line; i < len(lines); i++ {
		current := lines[i]
		if i == line-1 {
			declIdx := strings.Index(current, "=")
			if declIdx >= 0 {
				current = current[declIdx+1:]
			}
		}
		if pattern.MatchString(current) {
			return true
		}
	}
	return false
}

func isArrayReadLater(lines []string, name string, line int) bool {
	pattern := regexp.MustCompile(`\b` + regexp.QuoteMeta(name) + `\s*\[`)
	for i := line; i < len(lines); i++ {
		current := lines[i]
		if i == line-1 {
			assignIdx := strings.Index(current, "=")
			if assignIdx >= 0 {
				current = current[assignIdx+1:]
			}
		}
		if pattern.MatchString(current) {
			return true
		}
	}
	return false
}

func writeTextDiagnostics(w io.Writer, diags []diagnostic, cfg config) {
	for _, diag := range diags {
		_, _ = io.WriteString(w, formatTextDiagnostic(diag, cfg))
	}
}

func formatTextDiagnostic(diag diagnostic, cfg config) string {
	if cfg.template != "" {
		return formatTemplateDiagnostic(diag, cfg.template, cfg.templateLocation)
	}

	severity := diag.Severity
	if diag.File == "nofile" {
		return fmt.Sprintf("%s:%d:%d: %s: %s [%s]\n", diag.File, diag.Line, diag.Column, severity, diag.Message, diag.ID)
	}

	return formatSnippetDiagnostic(diag, severity)
}

func formatSnippetDiagnostic(diag diagnostic, severity string) string {
	var b strings.Builder
	_, _ = fmt.Fprintf(&b, "%s:%d:%d: %s: %s [%s]\n", diag.File, diag.Line, diag.Column, severity, diag.Message, diag.ID)
	if !diag.NoSnippet && diag.Code != "" {
		b.WriteString(diag.Code)
		b.WriteByte('\n')
		if diag.Column > 1 {
			b.WriteString(strings.Repeat(" ", diag.Column-1))
		}
		b.WriteString("^\n")
	}
	return b.String()
}

func formatTemplateDiagnostic(diag diagnostic, template, locationTemplate string) string {
	switch template {
	case "gcc":
		return formatSnippetDiagnostic(diag, "warning")
	case "cppcheck1":
		return fmt.Sprintf("[%s:%d]: (%s) %s\n", diag.File, diag.Line, diag.Severity, diag.Message)
	case "vs":
		return fmt.Sprintf("%s(%d): %s: %s\n", diag.File, diag.Line, diag.Severity, diag.Message)
	case "edit":
		return fmt.Sprintf("%s +%d: %s: %s\n", diag.File, diag.Line, diag.Severity, diag.Message)
	default:
		expanded := expandTemplate(template, diag, diag.Severity)
		if !strings.HasSuffix(expanded, "\n") {
			expanded += "\n"
		}
		if locationTemplate != "" && diag.Info != "" {
			loc := expandLocationTemplate(locationTemplate, diag)
			expanded += loc
			if !strings.HasSuffix(expanded, "\n") {
				expanded += "\n"
			}
		}
		return expanded
	}
}

func expandTemplate(template string, diag diagnostic, severity string) string {
	out := decodeEscapes(template)
	callstack := ""
	if diag.File != "" && diag.File != "nofile" {
		callstack = fmt.Sprintf("[%s:%d]", diag.File, diag.Line)
	}

	replacements := map[string]string{
		"{file}":     diag.File,
		"{line}":     strconv.Itoa(diag.Line),
		"{column}":   strconv.Itoa(diag.Column),
		"{callstack}": callstack,
		"{severity}": severity,
		"{message}":  diag.Message,
		"{id}":       diag.ID,
		"{cwe}":      diag.CWE,
		"{code}":     diag.Code,
	}
	for key, value := range replacements {
		out = strings.ReplaceAll(out, key, value)
	}

	for {
		start := strings.Index(out, "{inconclusive:")
		if start < 0 {
			break
		}
		end := strings.Index(out[start:], "}")
		if end < 0 {
			break
		}
		out = out[:start] + out[start+end+1:]
	}

	return out
}

func expandLocationTemplate(template string, diag diagnostic) string {
	out := decodeEscapes(template)
	replacements := map[string]string{
		"{file}":   diag.File,
		"{line}":   strconv.Itoa(diag.Line),
		"{column}": strconv.Itoa(diag.Column),
		"{info}":   diag.Info,
		"{code}":   diag.Code,
	}
	for key, value := range replacements {
		out = strings.ReplaceAll(out, key, value)
	}
	return out
}

func decodeEscapes(s string) string {
	replacer := strings.NewReplacer(`\t`, "\t", `\n`, "\n", `\r`, "\r")
	return replacer.Replace(s)
}

func writeXML(w io.Writer, diags []diagnostic) {
	results := xmlResults{
		Version: "2",
		Cppcheck: xmlCppcheck{
			Version: strings.TrimSpace(versionText[len("Cppcheck "):]),
		},
	}

	for _, diag := range diags {
		item := xmlError{
			ID:       diag.ID,
			Severity: diag.Severity,
			Msg:      diag.Message,
			Verbose:  diag.Message,
			CWE:      diag.CWE,
		}
		if diag.File != "" && diag.File != "nofile" && !diag.OmitFile0 {
			item.File0 = diag.File
		}
		if diag.File != "" && diag.File != "nofile" {
			item.Location = &xmlLocation{
				File:   diag.File,
				Line:   diag.Line,
				Column: diag.Column,
				Info:   diag.Info,
			}
		}
		if diag.Symbol != "" {
			s := diag.Symbol
			item.Symbol = &s
		}
		results.Errors = append(results.Errors, item)
	}

	body, _ := xml.MarshalIndent(results, "", "    ")
	_, _ = io.WriteString(w, xml.Header)
	_, _ = w.Write(body)
	_, _ = io.WriteString(w, "\n")
}

func writeSARIF(w io.Writer, diags []diagnostic) {
	log := sarifLog{
		Version: "2.1.0",
		Schema:  "https://json.schemastore.org/sarif-2.1.0.json",
		Runs: []sarifRun{{
			Tool: sarifTool{
				Driver: sarifDriver{
					Name:    "Cppcheck",
					Version: strings.TrimSpace(strings.TrimPrefix(versionText, "Cppcheck ")),
				},
			},
		}},
	}

	for _, diag := range diags {
		result := sarifResult{
			RuleID: diag.ID,
			Level:  sarifLevel(diag.Severity),
			Message: sarifMessage{
				Text: diag.Message,
			},
		}
		if diag.File != "" && diag.File != "nofile" {
			result.Locations = []sarifLocation{{
				PhysicalLocation: sarifPhysicalLocation{
					ArtifactLocation: sarifArtifactLocation{URI: diag.File},
					Region: sarifRegion{
						StartLine:   diag.Line,
						StartColumn: diag.Column,
					},
				},
			}}
		}
		log.Runs[0].Results = append(log.Runs[0].Results, result)
	}

	encoded, _ := json.MarshalIndent(log, "", "  ")
	_, _ = w.Write(encoded)
	_, _ = io.WriteString(w, "\n")
}

func sarifLevel(severity string) string {
	switch severity {
	case "error":
		return "error"
	case "style":
		return "warning"
	default:
		return "note"
	}
}

func isXMLFormat(format string) bool {
	return format == "xml"
}

func firstNonSpaceColumn(line string) int {
	for i, r := range line {
		if r != ' ' && r != '\t' {
			return i + 1
		}
	}
	return 1
}

func matchPath(pattern, path string) bool {
	if pattern == "" {
		return false
	}
	if ok, err := filepath.Match(pattern, path); err == nil && ok {
		return true
	}
	base := filepath.Base(path)
	if ok, err := filepath.Match(pattern, base); err == nil && ok {
		return true
	}
	return strings.Contains(path, pattern)
}

