func parseArgs(args []string) (config, []string, error) {
	cfg := config{outputFormat: "text"}
	var paths []string

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if !strings.HasPrefix(arg, "-") || arg == "-" {
			paths = append(paths, arg)
			continue
		}

		switch {
		case arg == "-q" || arg == "--quiet":
			cfg.quiet = true
		case arg == "--xml":
			cfg.outputFormat = "xml"
		case arg == "--inline-suppr":
			cfg.inlineSuppress = true
		case arg == "-f" || arg == "--force" || arg == "--inconclusive" || arg == "--check-config" || arg == "--check-library" || arg == "--dump" || arg == "-E" || arg == "--fsigned-char" || arg == "--funsigned-char" || arg == "--report-progress" || arg == "--safety" || arg == "-v" || arg == "--verbose":
			// Recognized no-op options.
		case arg == "-j" || arg == "-l" || arg == "-I" || arg == "-i" || arg == "-x":
			if i+1 >= len(args) {
				return cfg, nil, fmt.Errorf("unrecognized command line option: %q", arg)
			}
			val := args[i+1]
			i++
