package main

import (
	"os"
	"path/filepath"
	"testing"
)

func TestAnalyzeExtraCpp(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "extra.cpp")
	content := "int f()\n{\n    int x[2];\n    return x[3];\n}\n"
	if err := os.WriteFile(path, []byte(content), 0644); err != nil {
		t.Fatal(err)
	}

	diags := analyzeFile(inputFile{
		displayPath: path,
		realPath:    path,
		language:    "c++",
	}, config{})

	if len(diags) != 2 {
		t.Fatalf("got %d diagnostics: %#v", len(diags), diags)
	}
	if diags[0].ID != "arrayIndexOutOfBounds" {
		t.Fatalf("first diagnostic = %q", diags[0].ID)
	}
	if diags[1].ID != "uninitvar" {
		t.Fatalf("second diagnostic = %q", diags[1].ID)
	}
}

func TestAnalyzeOobC(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "oob.c")
	content := "int main()\n{\n    char a[10];\n    a[10] = 0;\n    return 0;\n}\n"
	if err := os.WriteFile(path, []byte(content), 0644); err != nil {
		t.Fatal(err)
	}

	diags := analyzeFile(inputFile{
		displayPath: path,
		realPath:    path,
		language:    "c",
	}, config{})

	if len(diags) != 1 {
		t.Fatalf("got %d diagnostics: %#v", len(diags), diags)
	}
	if diags[0].ID != "arrayIndexOutOfBounds" {
		t.Fatalf("diagnostic = %q", diags[0].ID)
	}
}

